module axixclk #(
		parameter integer C_S_AXI_ID_WIDTH	= 2,
		parameter integer C_S_AXI_DATA_WIDTH	= 32,
		parameter integer C_S_AXI_ADDR_WIDTH	= 6,
		parameter [0:0]	OPT_WRITE_ONLY = 1'b0,
		parameter [0:0]	OPT_READ_ONLY = 1'b0,
		parameter	XCLOCK_FFS = 2,
		parameter	LGFIFO = 5
	) (
		input	wire				S_AXI_ACLK,
		input	wire				S_AXI_ARESETN,
		input	wire [C_S_AXI_ID_WIDTH-1 : 0]	S_AXI_AWID,
		input	wire [C_S_AXI_ADDR_WIDTH-1 : 0]	S_AXI_AWADDR,
		input	wire [7 : 0]			S_AXI_AWLEN,
		input	wire [2 : 0]			S_AXI_AWSIZE,
		input	wire [1 : 0]			S_AXI_AWBURST,
		input	wire				S_AXI_AWLOCK,
		input	wire [3 : 0]			S_AXI_AWCACHE,
		input	wire [2 : 0]			S_AXI_AWPROT,
		input	wire [3 : 0]			S_AXI_AWQOS,
		input	wire				S_AXI_AWVALID,
		output	wire				S_AXI_AWREADY,
		input	wire [C_S_AXI_DATA_WIDTH-1 : 0]	S_AXI_WDATA,
		input	wire [(C_S_AXI_DATA_WIDTH/8)-1 : 0] S_AXI_WSTRB,
		input	wire				S_AXI_WLAST,
		input	wire				S_AXI_WVALID,
		output	wire				S_AXI_WREADY,
		output	wire [C_S_AXI_ID_WIDTH-1 : 0]	S_AXI_BID,
		output	wire [1 : 0]			S_AXI_BRESP,
		output	wire				S_AXI_BVALID,
		input	wire				S_AXI_BREADY,
		input	wire [C_S_AXI_ID_WIDTH-1 : 0]	S_AXI_ARID,
		input	wire [C_S_AXI_ADDR_WIDTH-1 : 0]	S_AXI_ARADDR,
		input	wire [7 : 0]			S_AXI_ARLEN,
		input	wire [2 : 0]			S_AXI_ARSIZE,
		input	wire [1 : 0]			S_AXI_ARBURST,
		input	wire				S_AXI_ARLOCK,
		input	wire [3 : 0]			S_AXI_ARCACHE,
		input	wire [2 : 0]			S_AXI_ARPROT,
		input	wire [3 : 0]			S_AXI_ARQOS,
		input	wire				S_AXI_ARVALID,
		output	wire				S_AXI_ARREADY,
		output	wire [C_S_AXI_ID_WIDTH-1 : 0]	S_AXI_RID,
		output	wire [C_S_AXI_DATA_WIDTH-1 : 0]	S_AXI_RDATA,
		output	wire [1 : 0]			S_AXI_RRESP,
		output	wire				S_AXI_RLAST,
		output	wire				S_AXI_RVALID,
		input	wire				S_AXI_RREADY,
		input	wire				M_AXI_ACLK,
		output	wire				M_AXI_ARESETN,
		output	wire [C_S_AXI_ID_WIDTH-1 : 0]	M_AXI_AWID,
		output	wire [C_S_AXI_ADDR_WIDTH-1 : 0]	M_AXI_AWADDR,
		output	wire [7 : 0]			M_AXI_AWLEN,
		output	wire [2 : 0]			M_AXI_AWSIZE,
		output	wire [1 : 0]			M_AXI_AWBURST,
		output	wire				M_AXI_AWLOCK,
		output	wire [3 : 0]			M_AXI_AWCACHE,
		output	wire [2 : 0]			M_AXI_AWPROT,
		output	wire [3 : 0]			M_AXI_AWQOS,
		output	wire				M_AXI_AWVALID,
		input	wire				M_AXI_AWREADY,
		output	wire [C_S_AXI_DATA_WIDTH-1 : 0]	M_AXI_WDATA,
		output	wire [(C_S_AXI_DATA_WIDTH/8)-1 : 0] M_AXI_WSTRB,
		output	wire				M_AXI_WLAST,
		output	wire				M_AXI_WVALID,
		input	wire				M_AXI_WREADY,
		input	wire [C_S_AXI_ID_WIDTH-1 : 0]	M_AXI_BID,
		input	wire [1 : 0]			M_AXI_BRESP,
		input	wire				M_AXI_BVALID,
		output	wire				M_AXI_BREADY,
		output	wire [C_S_AXI_ID_WIDTH-1 : 0]	M_AXI_ARID,
		output	wire [C_S_AXI_ADDR_WIDTH-1 : 0]	M_AXI_ARADDR,
		output	wire [7 : 0]			M_AXI_ARLEN,
		output	wire [2 : 0]			M_AXI_ARSIZE,
		output	wire [1 : 0]			M_AXI_ARBURST,
		output	wire				M_AXI_ARLOCK,
		output	wire [3 : 0]			M_AXI_ARCACHE,
		output	wire [2 : 0]			M_AXI_ARPROT,
		output	wire [3 : 0]			M_AXI_ARQOS,
		output	wire				M_AXI_ARVALID,
		input	wire				M_AXI_ARREADY,
		input	wire [C_S_AXI_ID_WIDTH-1 : 0]	M_AXI_RID,
		input	wire [C_S_AXI_DATA_WIDTH-1 : 0]	M_AXI_RDATA,
		input	wire [1 : 0]			M_AXI_RRESP,
		input	wire				M_AXI_RLAST,
		input	wire				M_AXI_RVALID,
		output	wire				M_AXI_RREADY
	);

	// Local parameters
	localparam integer FIFO_DEPTH = 1 << LGFIFO;
	localparam integer FIFO_ADDR_WIDTH = LGFIFO;
	localparam integer FFS_STAGES = XCLOCK_FFS;

	// Reset synchronization for M_AXI_ACLK domain
	reg [FFS_STAGES-1:0] m_reset_sync;
	always @(posedge M_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN)
			m_reset_sync <= {FFS_STAGES{1'b0}};
		else
			m_reset_sync <= {m_reset_sync[FFS_STAGES-2:0], 1'b1};
	end
	assign M_AXI_ARESETN = m_reset_sync[FFS_STAGES-1];

	// ========================================================================
	// AW Channel: S -> M
	// ========================================================================
	// AW data width
	localparam integer AW_DATA_WIDTH = C_S_AXI_ID_WIDTH + C_S_AXI_ADDR_WIDTH + 8 + 3 + 2 + 1 + 4 + 3 + 4;
	// AW FIFO
	reg [AW_DATA_WIDTH-1:0] aw_fifo_mem [0:FIFO_DEPTH-1];
	reg [FIFO_ADDR_WIDTH:0] aw_wr_ptr, aw_rd_ptr;
	wire aw_wr_en, aw_rd_en;
	wire aw_full, aw_empty;

	assign aw_full  = (aw_wr_ptr[FIFO_ADDR_WIDTH] != aw_rd_ptr[FIFO_ADDR_WIDTH]) &&
	                  (aw_wr_ptr[FIFO_ADDR_WIDTH-1:0] == aw_rd_ptr[FIFO_ADDR_WIDTH-1:0]);
	assign aw_empty = (aw_wr_ptr == aw_rd_ptr);

	// AW write side (S_AXI_ACLK domain)
	assign aw_wr_en = S_AXI_AWVALID && S_AXI_AWREADY;
	assign S_AXI_AWREADY = !aw_full;

	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN)
			aw_wr_ptr <= {FIFO_ADDR_WIDTH+1{1'b0}};
		else if (aw_wr_en)
			aw_wr_ptr <= aw_wr_ptr + 1'b1;
	end

	always @(posedge S_AXI_ACLK) begin
		if (aw_wr_en) begin
			aw_fifo_mem[aw_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= {
				S_AXI_AWID,
				S_AXI_AWADDR,
				S_AXI_AWLEN,
				S_AXI_AWSIZE,
				S_AXI_AWBURST,
				S_AXI_AWLOCK,
				S_AXI_AWCACHE,
				S_AXI_AWPROT,
				S_AXI_AWQOS
			};
		end
	end

	// AW read side (M_AXI_ACLK domain)
	assign aw_rd_en = M_AXI_AWREADY && !aw_empty;

	always @(posedge M_AXI_ACLK or negedge M_AXI_ARESETN) begin
		if (!M_AXI_ARESETN)
			aw_rd_ptr <= {FIFO_ADDR_WIDTH+1{1'b0}};
		else if (aw_rd_en)
			aw_rd_ptr <= aw_rd_ptr + 1'b1;
	end

	// AW output registers
	reg [C_S_AXI_ID_WIDTH-1:0] m_awid_reg;
	reg [C_S_AXI_ADDR_WIDTH-1:0] m_awaddr_reg;
	reg [7:0] m_awlen_reg;
	reg [2:0] m_awsize_reg;
	reg [1:0] m_awburst_reg;
	reg m_awlock_reg;
	reg [3:0] m_awcache_reg;
	reg [2:0] m_awprot_reg;
	reg [3:0] m_awqos_reg;
	reg m_awvalid_reg;

	always @(posedge M_AXI_ACLK or negedge M_AXI_ARESETN) begin
		if (!M_AXI_ARESETN) begin
			m_awid_reg    <= {C_S_AXI_ID_WIDTH{1'b0}};
			m_awaddr_reg  <= {C_S_AXI_ADDR_WIDTH{1'b0}};
			m_awlen_reg   <= 8'b0;
			m_awsize_reg  <= 3'b0;
			m_awburst_reg <= 2'b0;
			m_awlock_reg  <= 1'b0;
			m_awcache_reg <= 4'b0;
			m_awprot_reg  <= 3'b0;
			m_awqos_reg   <= 4'b0;
			m_awvalid_reg <= 1'b0;
		end else begin
			if (aw_rd_en) begin
				{m_awid_reg, m_awaddr_reg, m_awlen_reg, m_awsize_reg,
				 m_awburst_reg, m_awlock_reg, m_awcache_reg, m_awprot_reg,
				 m_awqos_reg} <= aw_fifo_mem[aw_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				m_awvalid_reg <= 1'b1;
			end else if (m_awvalid_reg && M_AXI_AWREADY) begin
				m_awvalid_reg <= 1'b0;
			end
		end
	end

	assign M_AXI_AWID    = m_awid_reg;
	assign M_AXI_AWADDR  = m_awaddr_reg;
	assign M_AXI_AWLEN   = m_awlen_reg;
	assign M_AXI_AWSIZE  = m_awsize_reg;
	assign M_AXI_AWBURST = m_awburst_reg;
	assign M_AXI_AWLOCK  = m_awlock_reg;
	assign M_AXI_AWCACHE = m_awcache_reg;
	assign M_AXI_AWPROT  = m_awprot_reg;
	assign M_AXI_AWQOS   = m_awqos_reg;
	assign M_AXI_AWVALID = m_awvalid_reg;

	// ========================================================================
	// W Channel: S -> M
	// ========================================================================
	// W data width
	localparam integer W_DATA_WIDTH = C_S_AXI_DATA_WIDTH + (C_S_AXI_DATA_WIDTH/8) + 1;
	// W FIFO
	reg [W_DATA_WIDTH-1:0] w_fifo_mem [0:FIFO_DEPTH-1];
	reg [FIFO_ADDR_WIDTH:0] w_wr_ptr, w_rd_ptr;
	wire w_wr_en, w_rd_en;
	wire w_full, w_empty;

	assign w_full  = (w_wr_ptr[FIFO_ADDR_WIDTH] != w_rd_ptr[FIFO_ADDR_WIDTH]) &&
	                 (w_wr_ptr[FIFO_ADDR_WIDTH-1:0] == w_rd_ptr[FIFO_ADDR_WIDTH-1:0]);
	assign w_empty = (w_wr_ptr == w_rd_ptr);

	// W write side (S_AXI_ACLK domain)
	assign w_wr_en = S_AXI_WVALID && S_AXI_WREADY;
	assign S_AXI_WREADY = !w_full;

	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN)
			w_wr_ptr <= {FIFO_ADDR_WIDTH+1{1'b0}};
		else if (w_wr_en)
			w_wr_ptr <= w_wr_ptr + 1'b1;
	end

	always @(posedge S_AXI_ACLK) begin
		if (w_wr_en) begin
			w_fifo_mem[w_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= {
				S_AXI_WDATA,
				S_AXI_WSTRB,
				S_AXI_WLAST
			};
		end
	end

	// W read side (M_AXI_ACLK domain)
	assign w_rd_en = M_AXI_WREADY && !w_empty;

	always @(posedge M_AXI_ACLK or negedge M_AXI_ARESETN) begin
		if (!M_AXI_ARESETN)
			w_rd_ptr <= {FIFO_ADDR_WIDTH+1{1'b0}};
		else if (w_rd_en)
			w_rd_ptr <= w_rd_ptr + 1'b1;
	end

	// W output registers - hold one extra M_AXI clock before M_AXI_WVALID
	reg [C_S_AXI_DATA_WIDTH-1:0] m_wdata_reg;
	reg [(C_S_AXI_DATA_WIDTH/8)-1:0] m_wstrb_reg;
	reg m_wlast_reg;
	reg m_wvalid_reg;
	reg w_valid_pending;

	always @(posedge M_AXI_ACLK or negedge M_AXI_ARESETN) begin
		if (!M_AXI_ARESETN) begin
			m_wdata_reg   <= {C_S_AXI_DATA_WIDTH{1'b0}};
			m_wstrb_reg   <= {(C_S_AXI_DATA_WIDTH/8){1'b0}};
			m_wlast_reg   <= 1'b0;
			m_wvalid_reg  <= 1'b0;
			w_valid_pending <= 1'b0;
		end else begin
			if (w_rd_en) begin
				{m_wdata_reg, m_wstrb_reg, m_wlast_reg} <= w_fifo_mem[w_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				w_valid_pending <= 1'b1;
			end else if (w_valid_pending) begin
				m_wvalid_reg <= 1'b1;
				w_valid_pending <= 1'b0;
			end else if (m_wvalid_reg && M_AXI_WREADY) begin
				m_wvalid_reg <= 1'b0;
			end
		end
	end

	assign M_AXI_WDATA  = m_wdata_reg;
	assign M_AXI_WSTRB  = m_wstrb_reg;
	assign M_AXI_WLAST  = m_wlast_reg;
	assign M_AXI_WVALID = m_wvalid_reg;

	// ========================================================================
	// B Channel: M -> S
	// ========================================================================
	// B data width
	localparam integer B_DATA_WIDTH = C_S_AXI_ID_WIDTH + 2;
	// B FIFO
	reg [B_DATA_WIDTH-1:0] b_fifo_mem [0:FIFO_DEPTH-1];
	reg [FIFO_ADDR_WIDTH:0] b_wr_ptr, b_rd_ptr;
	wire b_wr_en, b_rd_en;
	wire b_full, b_empty;

	assign b_full  = (b_wr_ptr[FIFO_ADDR_WIDTH] != b_rd_ptr[FIFO_ADDR_WIDTH]) &&
	                  (b_wr_ptr[FIFO_ADDR_WIDTH-1:0] == b_rd_ptr[FIFO_ADDR_WIDTH-1:0]);
	assign b_empty = (b_wr_ptr == b_rd_ptr);

	// B write side (M_AXI_ACLK domain)
	assign b_wr_en = M_AXI_BVALID && M_AXI_BREADY;
	assign M_AXI_BREADY = !b_full;

	always @(posedge M_AXI_ACLK or negedge M_AXI_ARESETN) begin
		if (!M_AXI_ARESETN)
			b_wr_ptr <= {FIFO_ADDR_WIDTH+1{1'b0}};
		else if (b_wr_en)
			b_wr_ptr <= b_wr_ptr + 1'b1;
	end

	always @(posedge M_AXI_ACLK) begin
		if (b_wr_en) begin
			b_fifo_mem[b_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= {
				M_AXI_BID,
				M_AXI_BRESP
			};
		end
	end

	// B read side (S_AXI_ACLK domain)
	assign b_rd_en = S_AXI_BREADY && !b_empty;

	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN)
			b_rd_ptr <= {FIFO_ADDR_WIDTH+1{1'b0}};
		else if (b_rd_en)
			b_rd_ptr <= b_rd_ptr + 1'b1;
	end

	// B output registers
	reg [C_S_AXI_ID_WIDTH-1:0] s_bid_reg;
	reg [1:0] s_bresp_reg;
	reg s_bvalid_reg;

	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN) begin
			s_bid_reg    <= {C_S_AXI_ID_WIDTH{1'b0}};
			s_bresp_reg  <= 2'b0;
			s_bvalid_reg <= 1'b0;
		end else begin
			if (b_rd_en) begin
				{s_bid_reg, s_bresp_reg} <= b_fifo_mem[b_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				s_bvalid_reg <= 1'b1;
			end else if (s_bvalid_reg && S_AXI_BREADY) begin
				s_bvalid_reg <= 1'b0;
			end
		end
	end

	assign S_AXI_BID    = s_bid_reg;
	assign S_AXI_BRESP  = s_bresp_reg;
	assign S_AXI_BVALID = s_bvalid_reg;

	// ========================================================================
	// AR Channel: S -> M
	// ========================================================================
	// AR data width
	localparam integer AR_DATA_WIDTH = C_S_AXI_ID_WIDTH + C_S_AXI_ADDR_WIDTH + 8 + 3 + 2 + 1 + 4 + 3 + 4;
	// AR FIFO
	reg [AR_DATA_WIDTH-1:0] ar_fifo_mem [0:FIFO_DEPTH-1];
	reg [FIFO_ADDR_WIDTH:0] ar_wr_ptr, ar_rd_ptr;
	wire ar_wr_en, ar_rd_en;
	wire ar_full, ar_empty;

	assign ar_full  = (ar_wr_ptr[FIFO_ADDR_WIDTH] != ar_rd_ptr[FIFO_ADDR_WIDTH]) &&
	                  (ar_wr_ptr[FIFO_ADDR_WIDTH-1:0] == ar_rd_ptr[FIFO_ADDR_WIDTH-1:0]);
	assign ar_empty = (ar_wr_ptr == ar_rd_ptr);

	// AR write side (S_AXI_ACLK domain)
	assign ar_wr_en = S_AXI_ARVALID && S_AXI_ARREADY;
	assign S_AXI_ARREADY = !ar_full;

	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN)
			ar_wr_ptr <= {FIFO_ADDR_WIDTH+1{1'b0}};
		else if (ar_wr_en)
			ar_wr_ptr <= ar_wr_ptr + 1'b1;
	end

	always @(posedge S_AXI_ACLK) begin
		if (ar_wr_en) begin
			ar_fifo_mem[ar_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= {
				S_AXI_ARID,
				S_AXI_ARADDR,
				S_AXI_ARLEN,
				S_AXI_ARSIZE,
				S_AXI_ARBURST,
				S_AXI_ARLOCK,
				S_AXI_ARCACHE,
				S_AXI_ARPROT,
				S_AXI_ARQOS
			};
		end
	end

	// AR read side (M_AXI_ACLK domain)
	assign ar_rd_en = M_AXI_ARREADY && !ar_empty;

	always @(posedge M_AXI_ACLK or negedge M_AXI_ARESETN) begin
		if (!M_AXI_ARESETN)
			ar_rd_ptr <= {FIFO_ADDR_WIDTH+1{1'b0}};
		else if (ar_rd_en)
			ar_rd_ptr <= ar_rd_ptr + 1'b1;
	end

	// AR output registers
	reg [C_S_AXI_ID_WIDTH-1:0] m_arid_reg;
	reg [C_S_AXI_ADDR_WIDTH-1:0] m_araddr_reg;
	reg [7:0] m_arlen_reg;
	reg [2:0] m_arsize_reg;
	reg [1:0] m_arburst_reg;
	reg m_arlock_reg;
	reg [3:0] m_arcache_reg;
	reg [2:0] m_arprot_reg;
	reg [3:0] m_arqos_reg;
	reg m_arvalid_reg;

	always @(posedge M_AXI_ACLK or negedge M_AXI_ARESETN) begin
		if (!M_AXI_ARESETN) begin
			m_arid_reg    <= {C_S_AXI_ID_WIDTH{1'b0}};
			m_araddr_reg  <= {C_S_AXI_ADDR_WIDTH{1'b0}};
			m_arlen_reg   <= 8'b0;
			m_arsize_reg  <= 3'b0;
			m_arburst_reg <= 2'b0;
			m_arlock_reg  <= 1'b0;
			m_arcache_reg <= 4'b0;
			m_arprot_reg  <= 3'b0;
			m_arqos_reg   <= 4'b0;
			m_arvalid_reg <= 1'b0;
		end else begin
			if (ar_rd_en) begin
				{m_arid_reg, m_araddr_reg, m_arlen_reg, m_arsize_reg,
				 m_arburst_reg, m_arlock_reg, m_arcache_reg, m_arprot_reg,
				 m_arqos_reg} <= ar_fifo_mem[ar_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				m_arvalid_reg <= 1'b1;
			end else if (m_arvalid_reg && M_AXI_ARREADY) begin
				m_arvalid_reg <= 1'b0;
			end
		end
	end

	assign M_AXI_ARID    = m_arid_reg;
	assign M_AXI_ARADDR  = m_araddr_reg;
	assign M_AXI_ARLEN   = m_arlen_reg;
	assign M_AXI_ARSIZE  = m_arsize_reg;
	assign M_AXI_ARBURST = m_arburst_reg;
	assign M_AXI_ARLOCK  = m_arlock_reg;
	assign M_AXI_ARCACHE = m_arcache_reg;
	assign M_AXI_ARPROT  = m_arprot_reg;
	assign M_AXI_ARQOS   = m_arqos_reg;
	assign M_AXI_ARVALID = m_arvalid_reg;

	// ========================================================================
	// R Channel: M -> S
	// ========================================================================
	// R data width
	localparam integer R_DATA_WIDTH = C_S_AXI_ID_WIDTH + C_S_AXI_DATA_WIDTH + 2 + 1;
	// R FIFO
	reg [R_DATA_WIDTH-1:0] r_fifo_mem [0:FIFO_DEPTH-1];
	reg [FIFO_ADDR_WIDTH:0] r_wr_ptr, r_rd_ptr;
	wire r_wr_en, r_rd_en;
	wire r_full, r_empty;

	assign r_full  = (r_wr_ptr[FIFO_ADDR_WIDTH] != r_rd_ptr[FIFO_ADDR_WIDTH]) &&
	                  (r_wr_ptr[FIFO_ADDR_WIDTH-1:0] == r_rd_ptr[FIFO_ADDR_WIDTH-1:0]);
	assign r_empty = (r_wr_ptr == r_rd_ptr);

	// R write side (M_AXI_ACLK domain)
	assign r_wr_en = M_AXI_RVALID && M_AXI_RREADY;
	assign M_AXI_RREADY = !r_full;

	always @(posedge M_AXI_ACLK or negedge M_AXI_ARESETN) begin
		if (!M_AXI_ARESETN)
			r_wr_ptr <= {FIFO_ADDR_WIDTH+1{1'b0}};
		else if (r_wr_en)
			r_wr_ptr <= r_wr_ptr + 1'b1;
	end

	always @(posedge M_AXI_ACLK) begin
		if (r_wr_en) begin
			r_fifo_mem[r_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= {
				M_AXI_RID,
				M_AXI_RDATA,
				M_AXI_RRESP,
				M_AXI_RLAST
			};
		end
	end

	// R read side (S_AXI_ACLK domain)
	assign r_rd_en = S_AXI_RREADY && !r_empty;

	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN)
			r_rd_ptr <= {FIFO_ADDR_WIDTH+1{1'b0}};
		else if (r_rd_en)
			r_rd_ptr <= r_rd_ptr + 1'b1;
	end

	// R output registers
	reg [C_S_AXI_ID_WIDTH-1:0] s_rid_reg;
	reg [C_S_AXI_DATA_WIDTH-1:0] s_rdata_reg;
	reg [1:0] s_rresp_reg;
	reg s_rlast_reg;
	reg s_rvalid_reg;

	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN) begin
			s_rid_reg    <= {C_S_AXI_ID_WIDTH{1'b0}};
			s_rdata_reg  <= {C_S_AXI_DATA_WIDTH{1'b0}};
			s_rresp_reg  <= 2'b0;
			s_rlast_reg  <= 1'b0;
			s_rvalid_reg <= 1'b0;
		end else begin
			if (r_rd_en) begin
				{s_rid_reg, s_rdata_reg, s_rresp_reg, s_rlast_reg} <= r_fifo_mem[r_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				s_rvalid_reg <= 1'b1;
			end else if (s_rvalid_reg && S_AXI_RREADY) begin
				s_rvalid_reg <= 1'b0;
			end
		end
	end

	assign S_AXI_RID    = s_rid_reg;
	assign S_AXI_RDATA  = s_rdata_reg;
	assign S_AXI_RRESP  = s_rresp_reg;
	assign S_AXI_RLAST  = s_rlast_reg;
	assign S_AXI_RVALID = s_rvalid_reg;

endmodule
